# Server Script: JMIT MRF API (method: jmit_mrf_data)
# RestrictedPython-safe. Commands: init, analytics, list, create_draft, create_submit

def get_filters():
    f = {}
    cmd_type = frappe.form_dict.get("cmd_type") or ""
    status = frappe.form_dict.get("status") or "All"
    warehouse = frappe.form_dict.get("warehouse") or frappe.form_dict.get("wh") or "All"
    return {"cmd_type": cmd_type, "status": status, "warehouse": warehouse}

def parse_items(raw):
    if not raw:
        return []
    if isinstance(raw, list):
        return raw
    s = raw.strip()
    if not s or s == "[]":
        return []
    s = s[1:-1]
    items, depth, cur = [], 0, ""
    for ch in s:
        if ch == "{":
            depth += 1
            if depth == 1:
                cur = ""; continue
        if ch == "}":
            depth -= 1
            if depth == 0:
                items.append(cur); cur = ""; continue
        cur += ch
    out = []
    for p in items:
        d = {}
        for pair in p.split(","):
            if ":" not in pair:
                continue
            kv = pair.split(":", 1)
            k = kv[0].strip().strip('"').strip("'")
            v = kv[1].strip()
            if v.startswith('"') or v.startswith("'"):
                d[k] = v.strip('"').strip("'")
            else:
                try:
                    d[k] = float(v) if "." in v else int(v)
                except:
                    d[k] = v
        out.append(d)
    return out

def cmd_init():
    whs = frappe.db.sql("SELECT name FROM `tabWarehouse` WHERE disabled = 0 ORDER BY name", as_dict=True)
    company = "JMIT"
    try:
        company = frappe.db.get_single_value("Global Defaults", "default_company") or "JMIT"
    except:
        pass
    return {"status": "success", "warehouses": whs, "company": company}

def cmd_analytics(filters):
    args = {}
    where = ""
    if filters["warehouse"] and filters["warehouse"] != "All":
        where = " WHERE t.warehouse = %(warehouse)s"
        args["warehouse"] = filters["warehouse"]
    total = frappe.db.sql("""SELECT COUNT(*) as c FROM `tabMaterial Request` t""" + where, args, as_dict=True)[0]["c"]
    pending = frappe.db.sql("""SELECT COUNT(*) as c FROM `tabMaterial Request` t WHERE t.status = 'Draft'""" + (where.replace("WHERE","AND") if where else ""), args, as_dict=True)[0]["c"]
    submitted = frappe.db.sql("""SELECT COUNT(*) as c FROM `tabMaterial Request` t WHERE t.status = 'Submitted'""" + (where.replace("WHERE","AND") if where else ""), args, as_dict=True)[0]["c"]
    by_status = frappe.db.sql("""SELECT t.status as status, COUNT(*) as count FROM `tabMaterial Request` t""" + where + """ GROUP BY t.status""", args, as_dict=True)
    top_items = frappe.db.sql("""SELECT ti.item_code, SUM(ti.qty) as qty FROM `tabMaterial Request Item` ti JOIN `tabMaterial Request` t ON ti.parent = t.name""" + where + """ GROUP BY ti.item_code ORDER BY qty DESC LIMIT 5""", args, as_dict=True)
    valuation = frappe.db.sql("""SELECT SUM(ti.amount) as v FROM `tabMaterial Request Item` ti JOIN `tabMaterial Request` t ON ti.parent = t.name""" + where, args, as_dict=True)[0]["v"] or 0
    wh_count = frappe.db.sql("""SELECT COUNT(DISTINCT t.warehouse) as c FROM `tabMaterial Request` t""" + where, args, as_dict=True)[0]["c"] or 0
    return {"status": "success", "kpis": {"total_requests": total, "pending": pending, "submitted": submitted, "total_items": 0, "total_valuation": valuation, "active_warehouses": wh_count}, "by_status": by_status, "top_items": top_items}

def cmd_list(filters):
    args = {}
    where = ""
    if filters["warehouse"] and filters["warehouse"] != "All":
        where = " WHERE t.warehouse = %(warehouse)s"
        args["warehouse"] = filters["warehouse"]
    if filters["status"] and filters["status"] != "All":
        where = (where + " AND " if where else " WHERE ") + "t.status = %(status)s"
        args["status"] = filters["status"]
    rows = frappe.db.sql("""SELECT t.name, t.status, t.material_request_type, t.schedule_date, t.warehouse, t.owner,
        (SELECT COUNT(*) FROM `tabMaterial Request Item` ti WHERE ti.parent = t.name) as item_count,
        (SELECT SUM(ti.qty) FROM `tabMaterial Request Item` ti WHERE ti.parent = t.name) as total_qty
        FROM `tabMaterial Request` t""" + where + """ ORDER BY t.creation DESC LIMIT 500""", args, as_dict=True)
    return {"status": "success", "requests": rows or []}

def cmd_create(filters):
    items_raw = frappe.form_dict.get("items") or "[]"
    items = parse_items(items_raw)
    if not items:
        return {"status": "error", "message": "No items"}
    wh = frappe.form_dict.get("warehouse") or ""
    dt = frappe.form_dict.get("schedule_date") or ""
    mtype = frappe.form_dict.get("material_request_type") or "Material Issue"
    submit = filters["cmd_type"] == "create_submit"
    try:
        mr = frappe.new_doc("Material Request")
        mr.material_request_type = mtype
        mr.schedule_date = dt
        mr.warehouse = wh
        for it in items:
            mr.append("items", {
                "item_code": it.get("item_code") or it.get("item") or "",
                "qty": float(it.get("qty") or 0),
                "uom": it.get("uom") or "Nos",
                "schedule_date": dt,
                "warehouse": wh
            })
        mr.insert(ignore_permissions=True)
        if submit:
            mr.submit()
            return {"status": "success", "name": mr.name, "submitted": True}
        return {"status": "success", "name": mr.name, "submitted": False}
    except Exception as e:
        return {"status": "error", "message": str(e)}

def handle_commands(filters):
    cmd = filters["cmd_type"]
    if not cmd:
        return None
    if cmd == "init":
        return cmd_init()
    if cmd == "analytics":
        return cmd_analytics(filters)
    if cmd == "list":
        return cmd_list(filters)
    if cmd in ("create_draft", "create_submit"):
        return cmd_create(filters)
    return None

def jmit_mrf_data():
    filters = get_filters()
    cmd_result = handle_commands(filters)
    if cmd_result is not None:
        frappe.response["message"] = cmd_result
    else:
        frappe.response["message"] = cmd_list(filters)

jmit_mrf_data()
